"""Offline corpus generated by the real v4 producer and serializer."""

from __future__ import annotations

import contextlib
import copy
import io
import json
import runpy
from pathlib import Path

from c2hunter_analysis.ddos_attack import analyze_ddos_attack
from c2hunter_analysis.ddos_signatures import EvidenceSample, digest
from c2hunter_controller.app import _validated_ddos_report

ROOT = Path(__file__).resolve().parents[2]


def build():
    with contextlib.redirect_stdout(io.StringIO()):
        seed = runpy.run_path(str(ROOT / "web/tests/ddos_report_fixture.py"))
    rows, parameters = (
        seed["records"],
        {
            "ddos_min_duration_seconds": 2,
            "ddos_min_source_count": 20,
            "ddos_min_packet_count": 1000,
            "ddos_min_packets_per_second": 10,
        },
    )
    sample = EvidenceSample()
    for row in rows:
        sample.add(row)
    snapshot = {
        "version": "ddos-normal-reference-v1",
        "records": sample.records,
        "reference": {
            "job_id": "normal-fixture",
            "dataset_id": "heldout-fixture",
            "content_digest": digest(sample.records),
            "record_count": len(sample.records),
            "selected_by": "fixture-operator",
            "selected_at": "2026-09-15T00:00:00Z",
            "coverage_limited": True,
        },
    }
    reports = {
        "absent-reference": seed["report"],
        "aggregate-reference": analyze_ddos_attack(
            rows, parameters=parameters, normal_reference=snapshot
        ),
    }
    packets = []
    for row in rows:
        packet = dict(
            row,
            packet_count=1,
            total_bytes=60,
            duration_seconds=0,
            tcp_flags={"syn": 1, "ack": 0, "rst": 0, "fin": 0},
            tcp_syn_count=1,
            tcp_syn_only_count=1,
            packet_evidence_complete=True,
        )
        packets.append(packet)
    policy = {
        **parameters,
        "ddos_min_packet_count": 6,
        "ddos_min_packets_per_second": 2,
    }
    reports["observed-packets"] = analyze_ddos_attack(packets, parameters=policy)
    result = []
    for name, report in reports.items():
        result.append({"name": name, "accepted": True, "report": report})
        result.append(
            {
                "name": name + "/serializer",
                "accepted": True,
                "report": _validated_ddos_report(report),
            }
        )
    for version in (2, 3):
        report = json.loads(
            (
                ROOT / f"web/tests/fixtures/ddos-report-contract-v{version}.json"
            ).read_text()
        )
        result.append(
            {"name": f"legacy-v{version}", "accepted": True, "report": report}
        )
    base = reports["absent-reference"]

    def mutation(name, path, value=None, absent=False):
        report = copy.deepcopy(base)
        node = report["findings"][0]["signature_candidates"][0]
        for part in path[:-1]:
            node = node[part]
        if absent:
            del node[path[-1]]
        else:
            node[path[-1]] = value
        result.append({"name": name, "accepted": False, "report": report})

    evaluation = base["findings"][0]["signature_candidates"][0]["evaluation"]
    for field in evaluation:
        mutation("absent/" + field, ["evaluation", field], absent=True)
        mutation("null/" + field, ["evaluation", field], None)
    for field in evaluation["attack"]:
        mutation("counts/absent/" + field, ["evaluation", "attack", field], absent=True)
    for value in (0, 0.5, 1):
        mutation(
            f"unobserved-rate/{value}",
            ["evaluation", "attack", "packet_match_rate"],
            value,
        )
    for field, value in [
        ("matched_records", 1),
        ("matched_packets", 1),
        ("eligible_records", True),
        ("sampled_records", 513),
        ("sample_bytes", 262145),
        ("unknown_packets", 0),
        ("record_limit", 513),
    ]:
        mutation("inconsistent/" + field, ["evaluation", "attack", field], value)
    mutation(
        "invented-normal", ["evaluation", "normal", "result"], evaluation["attack"]
    )
    mutation("missing-evaluation", ["evaluation"], absent=True)
    mutation("null-evaluation", ["evaluation"], None)
    mutation("foreign-target", ["evaluation", "predicate", "target_ip"], "10.0.0.99")
    mutation("numeric-approval", ["requires_human_approval"], 1)
    mutation("numeric-enforcement", ["evaluation", "automatic_enforcement"], 0)
    broadened = copy.deepcopy(base)
    candidate = broadened["findings"][0]["signature_candidates"][0]
    candidate["evaluation"]["predicate"]["tcp_flags"] = None
    candidate["id"] = "ddos-sig-" + digest(candidate["evaluation"]["predicate"])[:16]
    result.append(
        {
            "name": "rehashed-flag-profile-mismatch",
            "accepted": False,
            "report": broadened,
        }
    )
    base = reports["aggregate-reference"]
    mutation(
        "numeric-reference-coverage",
        ["evaluation", "normal", "reference", "coverage_limited"],
        1,
    )
    return result


if __name__ == "__main__":
    print(json.dumps(build(), sort_keys=True, separators=(",", ":")))
